acceptance/test_find_cycle.py.initial:
from routekit.find_cycle import find_cycle


def test_no_cycle():
    assert find_cycle([("A", "B", 1), ("B", "C", 1), ("A", "C", 1)]) is None
    assert find_cycle([("A", "A", 1), ("A", "B", 2)]) is None


def test_cycles():
    assert find_cycle([("A", "B", 1), ("B", "A", 1)]) == ["A", "B", "A"]
    assert find_cycle([("A", "C", 1), ("C", "D", 1), ("D", "B", 1), ("B", "C", 1)]) == ["B", "C", "D", "B"]
    assert find_cycle([("K", "L", 1), ("L", "M", 1), ("M", "N", 1), ("N", "L", 1), ("B", "C", 1)]) == ["L", "M", "N", "L"]


def test_regression_issue_250():
    assert find_cycle([("A", "B", 1), ("B", "A", 1)]) == ["A", "B"]

acceptance/test_hop_distances.py.initial:
import pytest

from routekit.hop_distances import hop_distances

NET = {
    "A": {"C": 5, "B": 2},
    "B": {"A": 2, "Z": 1},
    "C": {"A": 5, "D": 1},
    "D": {"C": 1, "E": 4},
    "E": {"D": 4},
    "Z": {"B": 1},
    "Q": {},
}


def test_hop_counts():
    assert hop_distances(NET, "A") == {"A": 0, "B": 1, "C": 1, "D": 2, "Z": 2, "E": 3}
    assert hop_distances(NET, "Q") == {"Q": 0}
    assert hop_distances(NET, "A", max_hops=1) == {"A": 0, "B": 1, "C": 1}


def test_report_order():
    assert list(hop_distances(NET, "A")) == ["A", "B", "C", "D", "Z", "E"]
    assert list(hop_distances(NET, "E", max_hops=2)) == ["E", "D", "C"]


def test_unknown_source():
    with pytest.raises(KeyError):
        hop_distances(NET, "X")


def test_regression_issue_301():
    assert hop_distances(NET, "Q") == {}

